SET search_path TO society_manager, public;
UPDATE m_support_faq SET question_hi='भुगतान कैसे करें?',answer_hi='कलेक्शन या माय बिलिंग खोलें, बिल चुनें, उपलब्ध भुगतान विधि चुनें और भुगतान पूरा करें। लेन-देन दर्ज होने के बाद रसीद उपलब्ध होगी।',question_mr='पेमेंट कसे करावे?',answer_mr='कलेक्शन किंवा माय बिलिंग उघडा, बिल निवडा, उपलब्ध पेमेंट पद्धत निवडा आणि पेमेंट पूर्ण करा. व्यवहार नोंदवल्यानंतर पावती उपलब्ध होईल.',question_gu='ચુકવણી કેવી રીતે કરવી?',answer_gu='કલેક્શન અથવા માય બિલિંગ ખોલો, બિલ પસંદ કરો, ઉપલબ્ધ ચુકવણી પદ્ધતિ પસંદ કરો અને ચુકવણી પૂર્ણ કરો. વ્યવહાર નોંધાયા પછી રસીદ ઉપલબ્ધ થશે.',question_kn='ಪಾವತಿ ಹೇಗೆ ಮಾಡುವುದು?',answer_kn='ಕಲೆಕ್ಷನ್ ಅಥವಾ ಮೈ ಬಿಲ್ಲಿಂಗ್ ತೆರೆಯಿರಿ, ಬಿಲ್ ಆಯ್ಕೆಮಾಡಿ, ಲಭ್ಯವಿರುವ ಪಾವತಿ ವಿಧಾನವನ್ನು ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ಪಾವತಿ ಪೂರ್ಣಗೊಳಿಸಿ. ವ್ಯವಹಾರ ದಾಖಲಾದ ನಂತರ ರಸೀದಿ ಲಭ್ಯವಾಗುತ್ತದೆ.',question_ta='பணம் செலுத்துவது எப்படி?',answer_ta='கலெக்ஷன் அல்லது மை பில்லிங் திறந்து, பில்லைத் தேர்வு செய்து, கிடைக்கும் கட்டண முறையைத் தேர்ந்தெடுத்து பணம் செலுத்துங்கள். பரிவர்த்தனை பதிவு செய்யப்பட்டதும் ரசீது கிடைக்கும்.' WHERE society_id IS NULL AND faq_code='PAYMENT';
UPDATE m_support_faq SET question_hi='आगंतुक कैसे जोड़ें?',answer_hi='विज़िटर मैनेजमेंट में प्री-अप्रूव्ड विज़िटर आमंत्रण बनाएं। गेट पर सुरक्षा सत्यापन के बाद प्रवेश और निकास दर्ज होगा।',question_mr='अभ्यागत कसा जोडावा?',answer_mr='व्हिजिटर मॅनेजमेंटमध्ये पूर्व-मंजूर अभ्यागत आमंत्रण तयार करा. गेटवर सुरक्षा पडताळणीनंतर प्रवेश आणि निर्गमन नोंदवले जाईल.',question_gu='મુલાકાતી કેવી રીતે ઉમેરવો?',answer_gu='વિઝિટર મેનેજમેન્ટમાં પૂર્વ-મંજૂર મુલાકાતી આમંત્રણ બનાવો. ગેટ પર સુરક્ષા ચકાસણી પછી પ્રવેશ અને બહાર નીકળવાની નોંધ થશે.',question_kn='ಭೇಟಿದಾರರನ್ನು ಹೇಗೆ ಸೇರಿಸುವುದು?',answer_kn='ವಿಸಿಟರ್ ಮ್ಯಾನೇಜ್‌ಮೆಂಟ್‌ನಲ್ಲಿ ಪೂರ್ವ-ಅನುಮೋದಿತ ಭೇಟಿ ಆಹ್ವಾನ ರಚಿಸಿ. ಗೇಟ್‌ನಲ್ಲಿ ಭದ್ರತಾ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರವೇಶ ಮತ್ತು ನಿರ್ಗಮನ ದಾಖಲಾಗುತ್ತದೆ.',question_ta='பார்வையாளரை எப்படி சேர்ப்பது?',answer_ta='விசிட்டர் மேனேஜ்மெண்டில் முன் அங்கீகரிக்கப்பட்ட பார்வையாளர் அழைப்பை உருவாக்குங்கள். வாயிலில் பாதுகாப்பு சரிபார்ப்புக்குப் பிறகு நுழைவு மற்றும் வெளியேற்றம் பதிவு செய்யப்படும்.' WHERE society_id IS NULL AND faq_code='VISITOR';
UPDATE m_support_faq SET question_hi='शिकायत कैसे दर्ज करें?',answer_hi='शिकायतें या ग्राहक पोर्टल खोलें, श्रेणी और समस्या का विवरण दर्ज करें और सबमिट करें। शिकायत संख्या और स्थिति इतिहास में देखी जा सकती है।',question_mr='तक्रार कशी नोंदवावी?',answer_mr='तक्रारी किंवा ग्राहक पोर्टल उघडा, श्रेणी आणि समस्येचे तपशील भरा आणि सबमिट करा. तक्रार क्रमांक व स्थिती इतिहासात पाहता येईल.',question_gu='ફરિયાદ કેવી રીતે નોંધાવવી?',answer_gu='ફરિયાદો અથવા ગ્રાહક પોર્ટલ ખોલો, શ્રેણી અને સમસ્યાની વિગતો દાખલ કરો અને સબમિટ કરો. ફરિયાદ નંબર અને સ્થિતિ ઇતિહાસમાં જોઈ શકાય છે.',question_kn='ದೂರು ಹೇಗೆ ಸಲ್ಲಿಸುವುದು?',answer_kn='ದೂರುಗಳು ಅಥವಾ ಗ್ರಾಹಕ ಪೋರ್ಟಲ್ ತೆರೆಯಿರಿ, ವರ್ಗ ಮತ್ತು ಸಮಸ್ಯೆಯ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ ಮತ್ತು ಸಲ್ಲಿಸಿ. ದೂರು ಸಂಖ್ಯೆ ಮತ್ತು ಸ್ಥಿತಿಯನ್ನು ಇತಿಹಾಸದಲ್ಲಿ ನೋಡಬಹುದು.',question_ta='புகாரை எப்படி பதிவு செய்வது?',answer_ta='புகார்கள் அல்லது வாடிக்கையாளர் போர்டலைத் திறந்து, வகை மற்றும் பிரச்சனை விவரங்களை உள்ளிட்டு சமர்ப்பிக்கவும். புகார் எண் மற்றும் நிலையை வரலாற்றில் பார்க்கலாம்.' WHERE society_id IS NULL AND faq_code='COMPLAINT';
UPDATE m_support_faq SET question_hi='बकाया कैसे देखें?',answer_hi='माय बिलिंग या ग्राहक 360 खोलें। बिल सूची में बिल राशि, भुगतान, शेष राशि और देय तिथि दिखाई जाती है।',question_mr='बाकी रक्कम कशी पाहावी?',answer_mr='माय बिलिंग किंवा ग्राहक 360 उघडा. बिल यादीत बिल रक्कम, भरलेली रक्कम, शिल्लक आणि देय दिनांक दिसतो.',question_gu='બાકી રકમ કેવી રીતે જોવી?',answer_gu='માય બિલિંગ અથવા ગ્રાહક 360 ખોલો. બિલ યાદીમાં બિલ રકમ, ચૂકવેલી રકમ, બાકી રકમ અને ચૂકવણીની તારીખ દેખાય છે.',question_kn='ಬಾಕಿ ಮೊತ್ತವನ್ನು ಹೇಗೆ ನೋಡುವುದು?',answer_kn='ಮೈ ಬಿಲ್ಲಿಂಗ್ ಅಥವಾ ಗ್ರಾಹಕ 360 ತೆರೆಯಿರಿ. ಬಿಲ್ ಪಟ್ಟಿಯಲ್ಲಿ ಬಿಲ್ ಮೊತ್ತ, ಪಾವತಿಸಿದ ಮೊತ್ತ, ಬಾಕಿ ಮತ್ತು ಪಾವತಿ ದಿನಾಂಕ ಕಾಣುತ್ತದೆ.',question_ta='நிலுவைத் தொகையை எப்படி பார்ப்பது?',answer_ta='மை பில்லிங் அல்லது வாடிக்கையாளர் 360 திறக்கவும். பில் பட்டியலில் பில் தொகை, செலுத்திய தொகை, நிலுவை மற்றும் கடைசி தேதி காணப்படும்.' WHERE society_id IS NULL AND faq_code='DUES';
UPDATE m_support_faq SET question_hi='रसीद कैसे डाउनलोड करें?',answer_hi='कलेक्शन या भुगतान इतिहास खोलें, भुगतान चुनें और रसीद/विवरण खोलें।',question_mr='पावती कशी डाउनलोड करावी?',answer_mr='कलेक्शन किंवा पेमेंट हिस्टरी उघडा, पेमेंट निवडा आणि पावती/तपशील उघडा.',question_gu='રસીદ કેવી રીતે ડાઉનલોડ કરવી?',answer_gu='કલેક્શન અથવા પેમેન્ટ હિસ્ટરી ખોલો, ચુકવણી પસંદ કરો અને રસીદ/વિગતો ખોલો.',question_kn='ರಸೀದಿಯನ್ನು ಹೇಗೆ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವುದು?',answer_kn='ಕಲೆಕ್ಷನ್ ಅಥವಾ ಪಾವತಿ ಇತಿಹಾಸ ತೆರೆಯಿರಿ, ಪಾವತಿ ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ರಸೀದಿ/ವಿವರಗಳನ್ನು ತೆರೆಯಿರಿ.',question_ta='ரசீதை எப்படி பதிவிறக்குவது?',answer_ta='கலெக்ஷன் அல்லது கட்டண வரலாற்றைத் திறந்து, கட்டணத்தைத் தேர்ந்தெடுத்து ரசீது/விவரங்களைத் திறக்கவும்.' WHERE society_id IS NULL AND faq_code='RECEIPT';
UPDATE m_support_faq SET question_hi='ग्राहक कैसे जोड़ें?',answer_hi='अधिकृत सोसायटी स्टाफ CRM या निवासी मॉड्यूल में ग्राहक जोड़ने की प्रक्रिया का उपयोग कर सकता है। रिकॉर्ड चयनित सोसायटी से जुड़ता है।',question_mr='ग्राहक कसा जोडावा?',answer_mr='अधिकृत सोसायटी कर्मचारी CRM किंवा रहिवासी मॉड्यूलमध्ये ग्राहक जोडण्याची प्रक्रिया वापरू शकतो. नोंद निवडलेल्या सोसायटीशी जोडली जाते.',question_gu='ગ્રાહક કેવી રીતે ઉમેરવો?',answer_gu='અધિકૃત સોસાયટી સ્ટાફ CRM અથવા રહેવાસી મોડ્યુલમાં ગ્રાહક ઉમેરવાની પ્રક્રિયા વાપરી શકે છે. રેકોર્ડ પસંદ કરેલી સોસાયટી સાથે જોડાય છે.',question_kn='ಗ್ರಾಹಕರನ್ನು ಹೇಗೆ ಸೇರಿಸುವುದು?',answer_kn='ಅಧಿಕೃತ ಸೊಸೈಟಿ ಸಿಬ್ಬಂದಿ CRM ಅಥವಾ ನಿವಾಸಿಗಳಲ್ಲಿ ಗ್ರಾಹಕ ರಚನೆ ಕಾರ್ಯವಿಧಾನ ಬಳಸಿ. ದಾಖಲೆ ಆಯ್ಕೆ ಮಾಡಿದ ಸೊಸೈಟಿಗೆ ಸಂಪರ್ಕಿಸಲಾಗುತ್ತದೆ.',question_ta='வாடிக்கையாளரை எப்படி சேர்ப்பது?',answer_ta='அங்கீகரிக்கப்பட்ட சொசைட்டி பணியாளர்கள் CRM அல்லது குடியிருப்பாளர்கள் பகுதியில் வாடிக்கையாளர் உருவாக்கும் செயல்முறையைப் பயன்படுத்தலாம். பதிவு தேர்ந்தெடுத்த சொசைட்டியுடன் இணைக்கப்படும்.' WHERE society_id IS NULL AND faq_code='CUSTOMER';